// CR-12: Volltext erfassen – Eingang. Erwartet document_id, mime_type, content_b64 oder (aus document_desk) ki_b64 + ctx.
const j = $input.first().json || {};
const ctx = j.ctx || {};
const id = String(j.document_id || ctx.document_id || '');
const mime = String(j.mime_type || ctx.ki_mime || ctx.mime_type || '');
const b64 = typeof j.content_b64 === 'string' ? j.content_b64 : (typeof j.ki_b64 === 'string' ? j.ki_b64 : '');
const quelle = String(j.quelle || 'upload').slice(0, 30);
let proj = '';
let proc = '';
try { proj = String($vars.JV_DOCAI_PROJECT || '').trim(); } catch (e) { proj = ''; }
try { proc = String($vars.JV_DOCAI_OCR_PROCESSOR || '').trim(); } catch (e) { proc = ''; }
const MIME = ['application/pdf', 'image/jpeg', 'image/png', 'image/tiff'];
let fehler = null;
if (!/^doc_[0-9A-Z]{26}$/.test(id)) fehler = 'Ungültige Dokument-ID';
else if (MIME.indexOf(mime) === -1) fehler = 'Dateityp für die Texterkennung nicht unterstützt: ' + mime.slice(0, 60);
else if (!b64) fehler = j.ladefehler ? 'Original nicht ladbar: ' + String(j.ladefehler).slice(0, 200) : 'Kein Dateiinhalt übergeben';
else if (b64.length > 27 * 1024 * 1024) fehler = 'Datei für die Texterkennung zu gross (über 20 MB)';
else if (!/^[a-z][a-z0-9-]{4,61}[a-z0-9]$/.test(proj) || !/^[a-f0-9]{8,32}$/.test(proc)) fehler = 'Konfiguration der Texterkennung fehlt (n8n-Variablen JV_DOCAI_PROJECT / JV_DOCAI_OCR_PROCESSOR).';
if (fehler) return [{ json: { ok_anfrage: false, document_id: id, quelle: quelle, fehler: fehler } }];
const body = { skipHumanReview: true, rawDocument: { mimeType: mime, content: b64 }, fieldMask: 'text,pages.pageNumber,pages.layout,pages.detectedLanguages' };
if (mime === 'application/pdf') body.imagelessMode = true;
return [{ json: { ok_anfrage: true, document_id: id, quelle: quelle, url: 'https://eu-documentai.googleapis.com/v1/projects/' + proj + '/locations/eu/processors/' + proc + ':process', body: body } }];

// CR-12: Antwort der Texterkennung auswerten und Speicherauftrag bilden. Volltext geht nur in die Datenbank, nie ins Protokoll.
const a = $('Anfrage bilden').first().json;
const r = $input.first().json || {};
let erg = null;
if (!a.ok_anfrage) {
  erg = { ok: false, document_id: a.document_id, quelle: a.quelle, fehler: a.fehler };
} else {
  const b = (r.body && typeof r.body === 'object') ? r.body : {};
  const st = Number(r.statusCode) || 0;
  if (st === 200 && b.document && typeof b.document === 'object') {
    const d = b.document;
    const pages = Array.isArray(d.pages) ? d.pages : [];
    const text = typeof d.text === 'string' ? d.text : '';
    const konf = pages.map(function (p) { return (p && p.layout && typeof p.layout.confidence === 'number') ? p.layout.confidence : null; }).filter(function (x) { return x !== null; });
    const mean = konf.length ? Math.round(konf.reduce(function (s, x) { return s + x; }, 0) / konf.length * 10000) / 10000 : null;
    const spr = {};
    pages.forEach(function (p) { (Array.isArray(p.detectedLanguages) ? p.detectedLanguages : []).forEach(function (l) { if (l && l.languageCode) spr[l.languageCode] = (spr[l.languageCode] || 0) + (Number(l.confidence) || 0); }); });
    const sprache = Object.keys(spr).sort(function (x, y) { return spr[y] - spr[x]; })[0] || null;
    erg = { ok: true, document_id: a.document_id, quelle: a.quelle, full_text: text, page_count: pages.length, mean_confidence: mean,
      sprache: sprache ? String(sprache).slice(0, 10) : null, provider: 'docai-ocr',
      pages: pages.map(function (p, ix) { return { nr: Number(p.pageNumber) || ix + 1, konfidenz: (p.layout && typeof p.layout.confidence === 'number') ? Math.round(p.layout.confidence * 10000) / 10000 : null }; }) };
  } else {
    const msg = b.error ? String(b.error.status || '') + ': ' + String(b.error.message || '').slice(0, 250) : ('HTTP ' + st + (r.error ? ' ' + String(r.error.message || r.error).slice(0, 200) : ''));
    erg = { ok: false, document_id: a.document_id, quelle: a.quelle, fehler: msg };
  }
}
return [{ json: { p64: Buffer.from(JSON.stringify(erg), 'utf8').toString('base64'), ok: erg.ok, document_id: erg.document_id, seiten: erg.page_count || 0, zeichen: erg.full_text ? erg.full_text.length : 0, konfidenz: erg.mean_confidence || null, fehler: erg.fehler || null } }];

// CR-12: knappes Ergebnis an den Aufrufer (ohne Volltext).
const e = $('Text auswerten').first().json;
const s = $input.first().json || {};
return [{ json: { ok: e.ok === true && Number(s.gespeichert || 0) + Number(s.dokument_gefunden || 0) > 0, document_id: e.document_id, seiten: e.seiten, zeichen: e.zeichen, konfidenz: e.konfidenz, gespeichert: Number(s.gespeichert || 0), fehler: e.fehler || (s.error ? 'Speichern fehlgeschlagen' : null) } }];
